cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // --- Quote: processing fee and single base premiums ---
  it.todo("quotes an empty item list as 5 G (processing fee only)");
  it.todo("quotes a plain sword as 105 G (100 G base + 5 G fee)");
  it.todo("quotes a plain amulet as 65 G (60 G base + 5 G fee)");
  it.todo("quotes a plain staff as 85 G (80 G base + 5 G fee)");
  it.todo("quotes a plain potion as 45 G (40 G base + 5 G fee)");
  it.todo("quotes a single rune as 30 G (25 G base + 5 G fee)");
  it.todo("quotes a single moonstone as 30 G (25 G base + 5 G fee)");

  // --- Quote: building block of 3 alike components ---
  it.todo("quotes 2 runes as base premium 50 G (no block)");
  it.todo("quotes 3 runes as base premium 60 G (block applies)");
  it.todo("quotes 4 runes as base premium 100 G (no block -- block requires exactly 3)");
  it.todo("quotes 7 runes as base premium 175 G (no block -- block requires exactly 3)");
  it.todo("quotes 2 runes + 1 moonstone as base premium 75 G (no block: different types)");
  it.todo("quotes 3 runes + 3 moonstones as base premium 120 G (two separate blocks)");

  // --- Quote: item-specific modifiers ---
  it.todo("adds a 50 % curse surcharge: cursed sword base 100 G -> 150 G");
  it.todo("adds a 30 % high-enchantment surcharge at enchantment exactly 5: sword base 100 G -> 130 G");
  it.todo("adds no high-enchantment surcharge at enchantment 4: sword base 100 G stays 100 G");
  it.todo("stacks curse and high enchantment on one item: cursed sword enchantment 5 -> base 180 G");
  it.todo("applies the curse surcharge only to the cursed item, not the policy total: cursed sword + plain amulet -> 210 G before policy modifiers and fee");

  // --- Quote: policy-wide modifiers ---
  it.todo("applies a 20 % loyalty discount at exactly 2 years with MHPCO: sword -> 80 G before fee");
  it.todo("applies no loyalty discount at 1 year with MHPCO: sword -> 100 G before fee");
  it.todo("applies a 10 % first-insurance surcharge on the policy base premium");
  it.todo("applies a 15 % follow-up discount on every contract after the customer's first quote");
  it.todo("applies the first-insurance surcharge even on a follow-up contract (each quoted item is a first insurance)");

  // --- Quote: rounding in the MHPCO's favor ---
  it.todo("rounds a premium of 197.5 G up to 198 G (MHPCO's favor)");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // --- Quote: integration examples ---
  it.todo("quotes a newcomer's cursed steel sword (enchantment 3, 0 years, first contract) as 165 G");
  it.todo("quotes a 3-year customer's second contract for a cursed sword (enchantment 7) as 160 G");

  // --- Quote: rejection ---
  it.todo("rejects a quote containing an unknown item type (e.g. broomstick): CLI exits non-zero, writes an error to stderr, and writes no results to stdout");

  // --- Claim: deductible and standard reimbursement ---
  it.todo("pays 400 G for a regular steel sword (enchantment 3) with damage 500 G (full reimbursement minus 100 G deductible)");
  it.todo("pays 100 G for a damaged rune with damage 200 G (no enchantment or material, so no special clause)");
  it.todo("applies the 100 G deductible once per damaged item: sword 500 G + amulet 300 G -> payout 600 G");

  // --- Claim: special clauses ---
  it.todo("reimburses 50 % for enchantment exactly 8: dragon sword, damage 1000 G -> payout 400 G");
  it.todo("fully reimburses dragon material at enchantment 5: damage 800 G -> payout 700 G");
  it.todo("lets the 50 % rule win over dragon material: dragon sword enchantment 9, damage 1000 G -> payout 400 G");
  it.todo("applies only the high-enchantment clause for a steel sword enchantment 9, damage 1000 G -> payout 400 G");

  // --- Claim: insurance sum and cap ---
  it.todo("caps a policy at twice the insurance sum: sword + amulet -> insurance sum 1600 G, cap 3200 G");
  it.todo("bases the cap on unmodified insurance values: cursed sword (premium 165 G) -> cap 2000 G");
  it.todo("excludes the block discount from the insurance sum: sword + 3 runes -> insurance sum 1750 G, cap 3500 G");
  it.todo("reduces a payout to the remaining cap: sword, two claims of 1500 G -> 1400 G (cap 600 G left), then 600 G (cap 0 G left)");

  // --- Claim: multiple items of the same type ---
  it.todo("sums insurance values for two swords: insurance sum 2000 G, cap 4000 G");
  it.todo("treats two sword damage entries as separate damages, each with its own deductible");
  it.todo("rejects a claim with more damage entries of a type than the policy covers: CLI exits non-zero and writes an error to stderr");

  // --- Claim: rounding and rejection ---
  it.todo("rounds a payout of 350.5 G down to 350 G (MHPCO's favor)");
  it.todo("rejects a claim for an item not covered by the policy (amulet damaged, only a sword insured): CLI exits non-zero and writes an error to stderr");
  it.todo("rejects a claim for an unknown item type: CLI exits non-zero and writes an error to stderr");
  it.todo("rejects a claim with a negative damage amount (-200): CLI exits non-zero and writes an error to stderr");

  // --- CLI end-to-end ---
  it.todo("reads a scenario from stdin and writes {results: [...]} to stdout in step order (schema example: quote amulet then claim 200 G)");
  it.todo("lets a later claim step reference the policy created by an earlier quote step via its zero-based index");
});
EOF
