export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

const PROCESSING_FEE = 5;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
};

// eslint-disable-next-line @typescript-eslint/no-unused-vars -- used once customer history modifiers are implemented
export function quote(customer: Customer, items: Item[]): number {
  const itemsBasePremium = items.reduce(
    (total, item) => total + BASE_PREMIUMS[item.type],
    0,
  );
  return itemsBasePremium + PROCESSING_FEE;
}
EOF
pnpm test 2>&1 | grep -E "Tests |Test Files"; npx tsc --noEmit && echo TSC_OK

